<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const fields = [
      {
        id: "full-name",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        required: true,
        error: "Error: Enter your full name."
      },
      {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        required: true,
        error: "Error: Enter a valid email address, like name@example.com."
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        helper: "Use digits, spaces, dashes, or parentheses. Example: (555) 123-4567.",
        error: "Error: Enter a phone number like (555) 123-4567, or leave this field blank."
      }
    ];

    function FormField(field) {
      const helperId = field.helper ? `${field.id}-helper` : "";
      const errorId = `${field.id}-error`;
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");
      const requiredLabel = field.required ? ' <span aria-hidden="true">*</span>' : " <span>(optional)</span>";
      const requiredAttribute = field.required ? "required" : "";

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${requiredLabel}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            ${requiredAttribute}
            aria-describedby="${describedBy}"
          >
          ${field.helper ? `<p class="helper-text" id="${helperId}">${field.helper}</p>` : ""}
          <p class="error-message" id="${errorId}">${field.error}</p>
        </div>
      `;
    }

    function SupportHero() {
      return `
        <section class="hero-panel" aria-labelledby="support-heading">
          <div>
            <div class="eyebrow">Support</div>
            <h1 id="support-heading">How can we help?</h1>
            <p>Send your details to our support team and we will route your request to the right specialist.</p>
          </div>
          <div class="response-note">
            <strong>Typical response time</strong>
            <span>Most requests receive a first reply within one business day.</span>
          </div>
        </section>
      `;
    }

    function ContactForm() {
      return `
        <section class="form-panel" aria-labelledby="contact-form-heading">
          <div class="form-intro">
            <h2 id="contact-form-heading">Contact support</h2>
            <p>Fields marked with an asterisk (*) are required.</p>
          </div>
          <form id="support-form" novalidate>
            <p class="required-note" aria-hidden="true">* Required fields</p>
            ${fields.map(FormField).join("")}
            <p class="status-message" id="form-status" aria-live="polite"></p>
            <button type="submit">Send request</button>
          </form>
        </section>
      `;
    }

    function App() {
      return `
        <main class="page-shell" id="main-content">
          <div class="support-card">
            ${SupportHero()}
            ${ContactForm()}
          </div>
        </main>
      `;
    }

    function setFieldError(input, message, showError) {
      input.setAttribute("aria-invalid", showError ? "true" : "false");
      message.classList.toggle("is-visible", showError);
    }

    function isValidPhone(value) {
      return value === "" || /^[+]?[0-9\s().-]{7,20}$/.test(value);
    }

    function validateField(input) {
      const errorMessage = document.getElementById(`${input.id}-error`);
      let showError = false;

      if (input.required && input.value.trim() === "") {
        showError = true;
      } else if (input.type === "email" && input.value.trim() !== "" && !input.validity.valid) {
        showError = true;
      } else if (input.type === "tel" && !isValidPhone(input.value.trim())) {
        showError = true;
      }

      setFieldError(input, errorMessage, showError);
      return !showError;
    }

    function attachValidation() {
      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const inputs = Array.from(form.querySelectorAll("input"));

      inputs.forEach((input) => {
        input.addEventListener("blur", () => validateField(input));
        input.addEventListener("input", () => {
          status.textContent = "";
          validateField(input);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        const firstInvalid = inputs.find((input) => !validateField(input));

        if (firstInvalid) {
          firstInvalid.focus();
          return;
        }

        form.reset();
        inputs.forEach((input) => {
          const errorMessage = document.getElementById(`${input.id}-error`);
          setFieldError(input, errorMessage, false);
        });
        status.textContent = "Thanks. Your support request is ready to send.";
      });
    }

    document.getElementById("root").innerHTML = App();
    attachValidation();
  </script>
</body>
</html>
