    function setFieldError(input, message, showError) {
      if (showError) {
        input.setAttribute("aria-invalid", "true");
      } else {
        input.removeAttribute("aria-invalid");
      }
      message.classList.toggle("is-visible", showError);
    }

    function isValidPhone(value) {
      return value === "" || /^[+]?[0-9\s().-]{7,20}$/.test(value);
    }

    function FormField(input, status) {
      const errorMessage = document.getElementById(`${input.id}-error`);

      function validate() {
        let showError = false;

        if (input.required && input.value.trim() === "") {
          showError = true;
        } else if (input.type === "email" && input.value.trim() !== "" && !input.validity.valid) {
          showError = true;
        } else if (input.type === "tel" && !isValidPhone(input.value.trim())) {
          showError = true;
        }

        setFieldError(input, errorMessage, showError);
        return !showError;
      }

      input.addEventListener("blur", validate);
      input.addEventListener("input", () => {
        status.textContent = "";
        validate();
      });

      return {
        input,
        validate,
        reset() {
          setFieldError(input, errorMessage, false);
        }
      };
    }

    function ContactForm(form) {
      const status = document.getElementById("form-status");
      const fieldComponents = Array.from(form.querySelectorAll("input")).map((input) => FormField(input, status));

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        const results = fieldComponents.map((field) => ({
          input: field.input,
          valid: field.validate()
        }));
        const firstInvalid = results.find((result) => !result.valid);

        if (firstInvalid) {
          firstInvalid.input.focus();
          return;
        }

        form.reset();
        fieldComponents.forEach((field) => field.reset());
        status.textContent = "Thanks. Your support request is ready to send.";
      });
    }

    ContactForm(document.getElementById("support-form"));
