 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main class="page-shell" id="main-content">
     <div class="support-card">
       <section class="hero-panel" aria-labelledby="support-heading">
         <div>
           <div class="eyebrow">Support</div>
           <h1 id="support-heading">How can we help?</h1>
           <p>Send your details to our support team and we will route your request to the right specialist.</p>
         </div>
         <div class="response-note">
           <strong>Typical response time</strong>
           <span>Most requests receive a first reply within one business day.</span>
         </div>
       </section>

       <section class="form-panel" aria-labelledby="contact-form-heading">
         <div class="form-intro">
           <h2 id="contact-form-heading">Contact support</h2>
           <p>Fields marked with an asterisk (*) are required.</p>
         </div>
         <form id="support-form" novalidate>
           <p class="required-note" aria-hidden="true">* Required fields</p>

           <div class="form-field">
             <label for="full-name">Full name <span aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="error-message" id="full-name-error">Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email">Email address <span aria-hidden="true">*</span></label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
             >
             <p class="error-message" id="email-error">Error: Enter a valid email address, like name@example.com.</p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span>(optional)</span></label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               aria-describedby="phone-helper phone-error"
             >
             <p class="helper-text" id="phone-helper">Use digits, spaces, dashes, or parentheses. Example: (555) 123-4567.</p>
             <p class="error-message" id="phone-error">Error: Enter a phone number like (555) 123-4567, or leave this field blank.</p>
           </div>

           <p class="status-message" id="form-status" aria-live="polite"></p>
           <button type="submit">Send request</button>
         </form>
       </section>
     </div>
   </main>

   <script>
     function setFieldError(input, message, showError) {
       if (showError) {
         input.setAttribute("aria-invalid", "true");
       } else {
         input.removeAttribute("aria-invalid");
       }
       message.classList.toggle("is-visible", showError);
     }

     function isValidPhone(value) {
       return value === "" || /^[+]?[0-9\s().-]{7,20}$/.test(value);
     }

     function FormField(input, status) {
       const errorMessage = document.getElementById(`${input.id}-error`);

       function validate() {
         let showError = false;

         if (input.required && input.value.trim() === "") {
           showError = true;
         } else if (input.type === "email" && input.value.trim() !== "" && !input.validity.valid) {
           showError = true;
         } else if (input.type === "tel" && !isValidPhone(input.value.trim())) {
           showError = true;
         }

         setFieldError(input, errorMessage, showError);
         return !showError;
       }

       input.addEventListener("blur", validate);
       input.addEventListener("input", () => {
         status.textContent = "";
         validate();
       });

       return {
         input,
         validate,
         reset() {
           setFieldError(input, errorMessage, false);
         }
       };
     }

     function ContactForm(form) {
       const status = document.getElementById("form-status");
       const fieldComponents = Array.from(form.querySelectorAll("input")).map((input) => FormField(input, status));

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         const results = fieldComponents.map((field) => ({
           input: field.input,
           valid: field.validate()
         }));
         const firstInvalid = results.find((result) => !result.valid);

         if (firstInvalid) {
           firstInvalid.input.focus();
           return;
         }

         form.reset();
         fieldComponents.forEach((field) => field.reset());
         status.textContent = "Thanks. Your support request is ready to send.";
       });
     }

     ContactForm(document.getElementById("support-form"));
   </script>
 </body>
